    /// defaults to true if SDL_HINT_RETURN_KEY_HIDES_IME is "0" or is not set, and defaults to false if
    /// SDL_HINT_RETURN_KEY_HIDES_IME is "1".</description>
    /// </item>
    /// </list>
    /// <para>On Android you can directly specify the input type:</para>
